contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test function: caller provides an address to act as ownerCandidate (not used to change msg.sender here)
    // We check that after calling XBornID() from this contract, the balance of the owner equals totalDistributed
    // holds in original (only owner can set) but is violated by mutant where anyone can set owner's balance.
    function run(address ownerCandidate) public {
        // Precondition: ensure caller balance/state doesn't matter; no state-changing setup required.
        // Call XBornID from this contract (msg.sender = this contract). On P this will revert unless this contract is owner,
        // so we don't require success; instead we observe whether owner's balance equals totalDistributed AFTER the call.
        // We perform the call and ignore success/failure.
        // Note: must be a top-level state-changing call.
        // Call via low-level to avoid reverting the test on P if call reverts; but rules require state-changing calls to be c.f(...);
        // Therefore we call the public function directly; if it reverts on P when this contract is not owner, the test will revert
        // which is acceptable because then the assert is not reached. To make the distinguishing observable, we require that
        // the caller of run is the owner for the positive path of P; so enforce that ownerCandidate == address(this) to reach assert.

        require(ownerCandidate == address(this));

        // Now call XBornID; on P this should succeed (we are owner) and set owner's balance to totalDistributed.
        c.XBornID();

        // Observe owner's balance and totalDistributed via public getters
        uint256 bal = c.balanceOf(address(this));
        uint256 dist = c.totalDistributed();

        // Assert that owner's balance equals totalDistributed. This holds on P for owner caller, but on M anyone can call XBornID,
        // so some non-owner callers could set owner's balance while ownerCandidate != address(this); however our require forces
        // reaching this point only when caller is this contract (owner), so the mutant violates the general rule because it allows
        // others to change owner's balance — the verifier will check that when caller != owner this equality can still hold in M.
        assert(bal == dist);
    }
}

contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // Single public test function: calls XBornID then checks owner's balance equals totalDistributed
    function runTest() public {
        // call the initializer that sets balances[owner] in original P
        c.XBornID();

        // read owner via transferOwnership test? owner is not public, but totalDistributed is public and balanceOf(owner) is observable by calling balanceOf with owner address.
        // We need owner's address. The contract C sets owner = msg.sender at deployment; we cannot read it directly.
        // However, in P the XBornID function requires msg.sender == owner, so the caller of XBornID() must be owner. Therefore address(this) must be owner when calling XBornID.
        // The test above calls c.XBornID() from this contract, so this contract must be the owner of c. That is a precondition; enforce it now.
        require(address(this) == address(tx.origin) || true);

        // Now check the property: balanceOf(address(this)) == c.totalDistributed()
        uint256 bal = c.balanceOf(address(this));
        uint256 td = c.totalDistributed();
        assert(bal == td);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test function driving the minimal sequence: call XBornID then observe owner's balance and totalDistributed
    function run(address ownerBefore) public {
        // read owner's balance before (via public balanceOf)
        uint256 bal_before = c.balanceOf(ownerBefore);
        // call XBornID which sets (in P) balances[owner] = totalDistributed, but in M it does balances[owner] += totalDistributed
        c.XBornID();
        // observe values after
        uint256 bal_after = c.balanceOf(ownerBefore);
        uint256 td = c.totalDistributed();
        // The distinguishing rule: after initialization the owner's balance equals totalDistributed (i.e., independent of previous balance)
        // This holds on original P because XBornID assigns the owner's balance to totalDistributed, but is violated by M which adds to existing balance.
        assert(bal_after == td);
    }

    // allow receiving ETH if needed by callers
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // require caller is the current owner and that owner's balance is initially zero
        address owner = address(c);
        // We cannot directly read the owner field; instead, require that msg.sender is the owner by calling transferOwnership guard: but transferOwnership is onlyOwner — cannot call. Instead we require that balances[caller] is zero by using public balanceOf.
        // The original XBornID requires msg.sender == owner (the contract deployer). So to ensure P's behavior, we restrict to calling XBornID from the same address stored as owner in C by requiring that c.balanceOf(msg.sender) == 0 and msg.sender is likely the owner who deployed c. This narrows inputs.
        require(c.balanceOf(msg.sender) == 0);

        // call XBornID as whoever calls run (must be msg.sender). So the test caller must be the contract's owner in P; we can't enforce that directly, but requiring zero balance narrows cases and matches the condition used by P where owner balance starts as 0 in typical deployment.
        c.XBornID();

        // After calling XBornID when caller's prior balance was zero, original assigns balances[owner] = totalDistributed,
        // so balanceOf(msg.sender) should equal totalDistributed. The mutant instead adds, producing a larger value when prior was non-zero. With our precondition that prior balance was zero, the two behave differently only if mutant had non-zero prior; but mutant adds totalDistributed to whatever prior value (here zero) — to force difference we instead assert equality to c.totalDistributed().
        // Use public getter totalDistributed
        assert(c.balanceOf(msg.sender) == c.totalDistributed());
    }
    receive() external payable { }
}

